// Read-only. EDITS mode: target translations changed in the window by a linguist account.
// MATCH mode: target translations whose English source equals one of the edited English strings.
const job = $('When called by parent').first().json;
const since = Number(job.since_ts || 0);
const LING = (job.linguists || []).map(function (x) { return String(x).toLowerCase(); });
const errors = [];
function asText(v) {
  if (v === null || v === undefined) { return ''; }
  if (typeof v === 'string') { return v; }
  try { return JSON.stringify(v); } catch (e) { return String(v); }
}
function norm(s) { return String(s || '').replace(/\s+/g, ' ').trim(); }
function filled(v) {
  const s = asText(v);
  if (!s.trim()) { return false; }
  if (s.charAt(0) !== '{') { return true; }
  try { const o = JSON.parse(s); return Object.values(o).some(function (x) { return String(x || '').trim(); }); } catch (e) { return true; }
}
function pages(nodeName) {
  const out = [];
  for (const p of $(nodeName).all()) {
    const j = p.json || {};
    if (j.error) { errors.push(nodeName + ': ' + JSON.stringify(j.error).slice(0, 200)); continue; }
    const b = j.body !== undefined ? j.body : j;
    if (!b || !Array.isArray(b.translations)) { errors.push(nodeName + ': page without translations'); continue; }
    for (const t of b.translations) { out.push(t); }
  }
  return out;
}
const EN = {};
for (const t of pages('Fetch EN')) { EN[t.key_id] = asText(t.translation); }
const tgt = pages('Fetch target');
const MATCH = {};
for (const m of (job.match || [])) { MATCH[norm(m)] = 1; }
const rows = [];
for (const t of tgt) {
  if (!filled(t.translation)) { continue; }
  const en = EN[t.key_id] || '';
  if (!en.trim()) { continue; }
  const by = String(t.modified_by_email || '').toLowerCase();
  const at = Number(t.modified_at_timestamp || 0);
  if (job.mode === 'edits') {
    if (at < since || LING.indexOf(by) === -1) { continue; }
  } else {
    if (!MATCH[norm(en)]) { continue; }
  }
  rows.push({ key_id: t.key_id, en: en.slice(0, 3000), text: asText(t.translation).slice(0, 3000), by: by, at: at, task: t.task_id || null, rev: !!t.is_reviewed });
}
const ids = rows.map(function (r) { return r.key_id; });
const chunks = [];
for (let i = 0; i < ids.length; i += 250) { chunks.push(ids.slice(i, i + 250).join(',')); }
if (!chunks.length) { chunks.push('0'); }
const base = { rows: rows, errors: errors, en_seen: Object.keys(EN).length, tgt_seen: tgt.length };
return chunks.map(function (c) { return { json: { ids: c, base: base } }; });

// Attach key name / description / tags; drop archived keys (never audited).
const job = $('When called by parent').first().json;
const procs = $('Process').all().map(function (i) { return i.json; });
const base = procs[0].base;
const info = {};
const errors = base.errors.slice();
for (const p of $input.all()) {
  const j = p.json || {};
  if (j.error) { errors.push('keys: ' + JSON.stringify(j.error).slice(0, 200)); continue; }
  const b = j.body !== undefined ? j.body : j;
  for (const k of ((b && b.keys) || [])) {
    const kn = k.key_name;
    const name = (kn && typeof kn === 'object') ? (kn.web || kn.other || kn.ios || kn.android || Object.values(kn)[0]) : kn;
    info[k.key_id] = { name: String(name || ''), d: String(k.description || '').slice(0, 400), tg: k.tags || [], arch: !!k.is_archived, cl: Number(k.char_limit || 0) };
  }
}
const rows = [];
let archived = 0;
let noinfo = 0;
for (const r of base.rows) {
  const i = info[r.key_id];
  if (!i) { noinfo++; continue; }
  if (i.arch) { archived++; continue; }
  rows.push(Object.assign({}, r, { k: i.name, d: i.d, tg: i.tg, cl: i.cl }));
}
return [{ json: { mode: job.mode, project_id: job.project_id, project_name: job.project_name, iso: job.iso, lang_name: job.lang_name,
  rows: rows, archived_skipped: archived, no_key_info: noinfo, en_seen: base.en_seen, tgt_seen: base.tgt_seen, errors: errors } }];

